using NetArchTest.Rules;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>
/// Guards the Domain -> Application -> Infrastructure layering so that a technical detail
/// (e.g. HTTP, file system, JSON attributes) can never leak into business-rule code.
/// </summary>
public sealed class LayeringTests
{
    private const string DomainNamespace = "PaymentAuthorization.Domain";
    private const string ApplicationNamespace = "PaymentAuthorization.Application";
    private const string InfrastructureNamespace = "PaymentAuthorization.Infrastructure";

    [Fact]
    public void Domain_does_not_depend_on_application_or_infrastructure()
    {
        var result = Types.InAssembly(typeof(Domain.Money).Assembly)
            .That().ResideInNamespace(DomainNamespace)
            .ShouldNot().HaveDependencyOnAny(ApplicationNamespace, InfrastructureNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
    {
        var result = Types.InAssembly(typeof(Application.AuthorizePayment).Assembly)
            .That().ResideInNamespace(ApplicationNamespace)
            .ShouldNot().HaveDependencyOnAny(InfrastructureNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_depend_on_framework_plumbing()
    {
        var result = Types.InAssembly(typeof(Application.AuthorizePayment).Assembly)
            .That().ResideInNamespace(ApplicationNamespace)
            .ShouldNot().HaveDependencyOnAny("System.Net.Http", "System.Text.Json", "System.IO")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    private static string Describe(TestResult result) =>
        result.IsSuccessful
            ? string.Empty
            : $"Layering violation in: {string.Join(", ", result.FailingTypeNames ?? [])}";
}
EOF
